// Native Compose adaptation of the existing NAXA Services stock/CRM form, with the same
// server-confirmed action contract as Web. No raw JSON, tenant or identifier entry.
internal class ND(val data:Map<String,JSONObject>){
 fun rows(ds:String,arr:String)=data[ds]?.rows(arr).orEmpty()
 fun find(ds:String,arr:String,id:String?)=rows(ds,arr).firstOrNull{it.optString("id")==id}?:JSONObject()
 fun cash()=data["snapshot"]?.optJSONObject("cash_session")?.optString("id")?.takeIf{it.isNotBlank()}?:error("CASH_REQUIRED")
}
private fun display(o:JSONObject,key:String):String {
 val name=o.optString(key).takeUnless{it.isBlank()||it=="null"}?:o.optString("name").ifBlank{o.optString("label").ifBlank{"#"+o.optString("id").take(8)}}
 val safe=if(name.matches(Regex("[a-f0-9-]{36}")))"#"+name.take(8) else name
 val money=listOf("amount_xaf","total_xaf","balance_xaf","expected_xaf","remaining_cost_xaf","approved_value","restock_cost").firstNotNullOfOrNull{k->o.optString(k).takeIf{it.isNotBlank()&&it!="null"}}
 return safe+(money?.let{" · "+it+" FCFA"}?:"")
}
private fun opts(rows:List<JSONObject>,id:String,label:String)=rows.mapNotNull{v->v.optString(id).takeIf{it.isNotBlank()&&it!="null"}?.let{it to display(v,label)}}
internal data class NF(val key:String,val fr:String,val en:String,val type:String,val optional:Boolean=false,val options:(ND,Map<String,String>)->List<Pair<String,String>> = {_,_->emptyList()},val visible:(Map<String,String>)->Boolean={true})
