private fun fieldBody(fields:List<NF>,data:ND,values:Map<String,String>):JSONObject{
 val body=JSONObject()
 for(f in fields){
  if(!f.visible(values)){body.put(f.key,JSONObject.NULL);continue}
  val raw=values[f.key].orEmpty().trim()
  if(raw.isEmpty()&&f.optional){body.put(f.key,JSONObject.NULL);continue}
  require(raw.isNotEmpty())
  val v:Any=when(f.type){
   "select"->{require(f.options(data,values).any{it.first==raw});raw}
   "int","zero"->{val n=ZippleErpNumbers.integer(raw)?:error("INVALID_AMOUNT");require(n>0||f.type=="zero");n}
   "milli","milli0"->{val n=ZippleErpNumbers.milli(raw)?:error("INVALID_QUANTITY");require(n in (if(f.type=="milli0")0L else 1L)..1000000000L);n}
   "exact"->{require(Regex("[1-9][0-9]{0,17}").matches(raw));raw}
   "date"->{LocalDate.parse(raw);raw}
   "reason"->{require(raw.length in 5..500);raw}
   else->{require(raw.length<=500);raw}
  }
  body.put(f.key,v)
 }
 return body
}
internal fun bulk3Body(form:NA,data:ND,values:Map<String,String>,repeated:List<Map<String,String>> = emptyList()):JSONObject{
 val body=form.build(fieldBody(form.fields,data,values),data,values)
 if(form.repeatFields.isNotEmpty()){
  require(repeated.size in form.minRows..form.maxRows)
  val rows=repeated.map{fieldBody(form.repeatFields,data,it)}
  if(form.arrayKey=="lines"&&form.action.startsWith("ledger")){
   require(rows.map{it.getString("account_id")}.distinct().size==rows.size)
   val amount=if(form.action=="ledger_correct")data.find("ledger_snapshot","entries",values["entry_id"]).getString("amount_xaf") else data.rows("ledger_snapshot","pending").first{it.optString("kind")+":"+it.optString("source_id")==values["source"]}.getString("amount_xaf")
   val total=java.math.BigInteger(amount)
   require(listOf("debit","credit").all{side->rows.filter{it.getString("side")==side}.fold(java.math.BigInteger.ZERO){sum,row->sum+java.math.BigInteger(row.getString("amount_xaf"))}==total})
  }
  if(form.arrayKey=="components")require(rows.map{it.getString("ingredient_id")}.distinct().size==rows.size)
  if(form.arrayKey=="tenders"){
   require(rows.map{it.getString("method")}.distinct().size==rows.size)
   require(rows.sumOf{it.getLong("amount_xaf")}==data.find("snapshot","orders",values["order_id"]).getLong("total_xaf"))
   require(rows.all{it.getString("method")=="cash"||it.optString("reference").length>=4})
  }
  body.put(form.arrayKey,JSONArray().also{a->rows.forEach{a.put(it)}})
 }
 return body
}
@Composable private fun BulkChoice(label:String,options:List<Pair<String,String>>,value:String,change:(String)->Unit,enabled:Boolean){
 var open by remember{mutableStateOf(false)}
 Box{OutlinedButton(enabled=enabled&&options.isNotEmpty(),onClick={open=true}){Text(label+" : "+(options.firstOrNull{it.first==value}?.second?:"—"))};DropdownMenu(expanded=open,onDismissRequest={open=false}){options.forEach{(id,name)->DropdownMenuItem(text={Text(name)},onClick={change(id);open=false})}}}
}
@Composable internal fun ZippleNativeBulk3(api:ZippleBusiness,session:Session,site:String,en:Boolean){
 Bulk3Screen(session.role,session.permits(site),en,{action,body->api.call(session,site,action,body)})
}
@Composable internal fun Bulk3Screen(role:String,allowed:Boolean,en:Boolean,call:suspend(String,JSONObject)->Any?){
 val tr:(String,String)->String={fr,eng->if(en)eng else fr}
 val scope=rememberCoroutineScope();val groups=bulk3Groups.filter{!it.owner||role=="promoteur"}
 var groupId by remember{mutableStateOf("purchases")};var formIndex by remember{mutableStateOf(0)}
 var data by remember{mutableStateOf(ND(emptyMap()))};var values by remember{mutableStateOf<Map<String,String>>(emptyMap())};var busy by remember{mutableStateOf(false)};var loaded by remember{mutableStateOf(false)};var message by remember{mutableStateOf("")};var result by remember{mutableStateOf<JSONObject?>(null)}
 val group=groups.firstOrNull{it.id==groupId}?:groups.first()
 val forms=group.forms.filter{!it.owner||role=="promoteur"};val form=forms.getOrNull(formIndex)?:forms.first()
 var repeated by remember(group.id,formIndex){mutableStateOf(List(form.minRows){emptyMap<String,String>()})}
 val keys=remember{RequestKeys()}
 suspend fun refresh(){val map=mutableMapOf<String,JSONObject>();for(action in group.loads)map[action]=call(action,JSONObject()) as? JSONObject?:error("DATA_UNAVAILABLE");data=ND(map);loaded=true}
 fun run(block:suspend()->Unit){if(busy||!allowed)return;busy=true;message="";scope.launch{try{block()}catch(c:CancellationException){throw c}catch(_:Exception){message=tr("Opération non confirmée","Operation unconfirmed")}finally{busy=false}}}
 LaunchedEffect(group.id){data=ND(emptyMap());loaded=false;result=null;try{refresh()}catch(c:CancellationException){throw c}catch(_:Exception){message=tr("Données indisponibles","Data unavailable")}}
 Text(tr("Gestion des stocks et finances","Inventory and finance management"),style=MaterialTheme.typography.titleLarge)
 BulkChoice(tr("Espace","Workspace"),groups.map{it.id to tr(it.fr,it.en)},group.id,{groupId=it;formIndex=0;values=emptyMap()},!busy)
 OutlinedButton(enabled=allowed&&!busy,onClick={run{refresh()}}){Text(tr("Actualiser les données","Refresh data"))}
 BulkChoice(tr("Action","Action"),forms.mapIndexed{i,a->i.toString() to tr(a.fr,a.en)},forms.indexOf(form).toString(),{formIndex=it.toInt();values=emptyMap();result=null},!busy)
 Text(tr(form.fr,form.en),style=MaterialTheme.typography.titleMedium)
 for(f in form.fields.filter{it.visible(values)}){
  key(group.id,formIndex,f.key){
   val label=tr(f.fr,f.en);val value=values[f.key].orEmpty()
   if(f.type=="select")BulkChoice(label,f.options(data,values),value,{v->values=values+(f.key to v)},!busy&&loaded)
   else OutlinedTextField(value,{v->values=values+(f.key to v.take(500))},modifier=Modifier.fillMaxWidth(),label={Text(label)},singleLine=true,enabled=!busy&&loaded,keyboardOptions=KeyboardOptions(keyboardType=if(f.type in setOf("int","zero","milli","milli0"))KeyboardType.Decimal else KeyboardType.Text))
  }
 }
 if(form.repeatFields.isNotEmpty()){
  repeated.forEachIndexed{idx,row->
   key(group.id,formIndex,idx){
    Text(tr("Ligne","Line")+" "+(idx+1),style=MaterialTheme.typography.titleSmall)
    form.repeatFields.filter{it.visible(row)}.forEach{f->
     val label=tr(f.fr,f.en);val value=row[f.key].orEmpty()
     val change:(String)->Unit={v->repeated=repeated.mapIndexed{j,old->if(j==idx)old+(f.key to v)else old}}
     if(f.type=="select")BulkChoice(label,f.options(data,row),value,change,!busy&&loaded)
     else OutlinedTextField(value,change,modifier=Modifier.fillMaxWidth(),label={Text(label)},singleLine=true,enabled=!busy&&loaded,keyboardOptions=KeyboardOptions(keyboardType=if(f.type in setOf("int","zero","milli","milli0","exact"))KeyboardType.Decimal else KeyboardType.Text))
    }
    if(repeated.size>form.minRows)OutlinedButton(enabled=!busy,onClick={repeated=repeated.filterIndexed{j,_->j!=idx}}){Text(tr("Retirer la ligne","Remove line")+" "+(idx+1))}
   }
  }
  OutlinedButton(enabled=!busy&&repeated.size<form.maxRows,onClick={repeated=repeated+listOf(emptyMap())}){Text(tr("Ajouter une ligne","Add line"))}
 }
 val body=runCatching{bulk3Body(form,data,values,repeated)}.getOrNull()
 Button(enabled=allowed&&loaded&&!busy&&body!=null,onClick={run{
   val payload=requireNotNull(body);val response=call(form.action,keys.apply(form.action,payload));keys.confirmed(form.action)
   result=response as? JSONObject;values=emptyMap();repeated=List(form.minRows){emptyMap()};message=tr("Opération confirmée","Operation confirmed");refresh()
 }}){Text(tr("Confirmer","Confirm"))}
 result?.let{r->
  val fields=listOf("assets_xaf" to tr("Actifs","Assets"),"liabilities_xaf" to tr("Dettes","Liabilities"),"equity_xaf" to tr("Capitaux propres","Equity"),"revenue_xaf" to tr("Produits","Revenue"),"expenses_xaf" to tr("Charges","Expenses"),"result_xaf" to tr("Résultat","Result"),"variance_xaf" to tr("Écart caisse","Cash variance"),"unclassified" to tr("Comptes non classés","Unclassified accounts"),"pending_sources" to tr("Sources non comptabilisées","Unposted sources"))
  fields.forEach{(k,label)->if(r.has(k))Text(label+" : "+r.optString(k))}
  if(r.has("sites_included")){Text(tr("Établissements couverts","Included sites")+" : "+r.optString("sites_included")+"/"+r.optString("sites_total"));r.rows("sites").forEach{Text(it.optString("site_name")+" · "+it.optString("result_xaf")+" FCFA")};if(!r.optBoolean("complete_scope")||!r.optBoolean("all_closed"))Text(tr("Consolidation provisoire ou partielle","Provisional or partial consolidation"))}
  if(r.has("closed_through")&&(r.isNull("closed_through")||r.optString("closed_through")<r.optString("to")))Text(tr("États provisoires, période non clôturée.","Provisional statements, period not closed."))
 }
 if(message.isNotBlank())Text(message)
 for((ds,arr,label) in group.summaries){val rows=data.rows(ds,arr);if(rows.isNotEmpty()){HorizontalDivider(Modifier.padding(vertical=6.dp));rows.take(40).forEach{x->Text(display(x,label)+" · "+x.optString("state").takeUnless{it=="null"}.orEmpty())}}}
}
